import json,re
from pathlib import Path
p=Path("index.html")
s=p.read_text()
owners={"2020":[["Seth Miller","Jordan Martin","Payton Docheff","Seth Miller","Jordan Martin","Seth Miller","Seth Miller","Matthew Piontek","Seth Miller","Alex Agueros","Matt Metz","Seth Miller"],["Seth Miller","Seth Miller","Seth Miller","David Carnes","Jordan Martin","Matt Clawson","Jordan Martin","Matthew Piontek","Seth Miller","Mason Good","Matt Metz","Seth Miller"],["Mason Good","Mason Good","Seth Miller","Kevin Long","Alex Agueros","Matt Clawson","Bo Tiller","Matthew Piontek","Matt Clawson","Seth Miller","Matt Metz","Alex Agueros"],["Seth Miller","Mason Good","Payton Docheff","Kevin Long","Mason Good","Alex Agueros","Bo Tiller","Travis Page","Seth Miller","Alex Agueros","Matt Metz","Kevin Long"]],"2021":[["Jordan Martin","Payton Docheff","Jordan Martin","Matt Metz","Luke Miller","Seth Miller","Bo Tiller","Payton Docheff","Mason Good","Matt Clawson","Matt Clawson","Matthew Piontek"],["Jordan Martin","Matt Metz","Seth Miller","Matt Metz","Payton Docheff","Travis Page","Seth Miller","Matt Clawson","Mason Good","Alex Agueros","Seth Miller","Jordan Martin"],["Luke Miller","Matt Clawson","Matt Metz","Payton Docheff","Travis Page","Alex Agueros","Jordan Martin","Bo Tiller","Mason Good","Payton Docheff","Matt Clawson","Matthew Piontek"],["Payton Docheff","Alex Agueros","Matt Clawson","Matt Metz","Luke Miller","Bo Tiller","Matthew Piontek","Bo Tiller","Mason Good","Matthew Piontek","Matt Clawson","Matthew Piontek"]],"2022":[["Seth Miller","Travis Page","Payton Docheff","Travis Page","Travis Page","Jordan Martin","Matt Metz","Travis Page","Bo Tiller","Alex Agueros","Matt Clawson","Luke Miller"],["David Carnes","Seth Miller","Luke Miller","David Carnes","Payton Docheff","David Carnes","Matt Metz","Travis Page","David Carnes","Matt Clawson","Payton Docheff","Travis Page"],["Payton Docheff","Bo Tiller","Mason Good","Matt Clawson","Mason Good","Mason Good","Matt Metz","Payton Docheff","Bo Tiller","Alex Agueros","Alex Agueros","Alex Agueros"],["Seth Miller","Bo Tiller","Seth Miller","Matt Clawson","Alex Agueros","Mason Good","Matt Clawson","Matt Clawson","Bo Tiller","Jordan Martin","Luke Miller","Luke Miller"]],"2023":[["Travis Page","Travis Page","Luke Miller","Jordan Martin","Matt Clawson","Payton Docheff","Alex Agueros","Jordan Martin","Tim Bell","Bo Tiller","Matt Metz","Seth Miller"],["Luke Miller","Travis Page","Luke Miller","Payton Docheff","David Carnes","Payton Docheff","Mason Good","Jordan Martin","Tim Bell","Bo Tiller","Matt Metz","Payton Docheff"],["Seth Miller","Luke Miller","Alex Agueros","Mason Good","Mason Good","Travis Page","Alex Agueros","Payton Docheff","Tim Bell","Bo Tiller","Matt Metz","Bo Tiller"],["Matt Clawson","Travis Page","Luke Miller","Alex Agueros","Alex Agueros","Payton Docheff","Luke Miller","Matt Clawson","Luke Miller","Seth Miller","Travis Page","Luke Miller"],["Matt Clawson","Travis Page","Luke Miller","Mason Good","Matt Metz","Payton Docheff","Alex Agueros","Matt Clawson","Tim Bell","Bo Tiller","Matt Metz","Bo Tiller"],["Matt Clawson","Travis Page","Luke Miller","Mason Good","Matt Metz","Payton Docheff","Alex Agueros","Matt Clawson","Tim Bell","Seth Miller","Jordan Martin","Seth Miller"]],"2024":[["Seth Miller","Seth Miller","David Carnes","Seth Miller","Clint Hudson","Luke Miller","Bo Tiller","Ryan Lipkin","Matt Metz","David Carnes","Alex Agueros","David Carnes"],["Matt Clawson","Luke Miller","Alex Agueros","Matt Clawson","Clint Hudson","Alex Agueros","Bo Tiller","Travis Page","Matt Metz","Seth Miller","Alex Agueros","Alex Agueros"],["Matt Clawson","Travis Page","Travis Page","Ryan Lipkin","Clint Hudson","David Carnes","Bo Tiller","Seth Miller","Matt Metz","Payton Docheff","Alex Agueros","Seth Miller"],["Matt Clawson","Luke Miller","Payton Docheff","Ryan Lipkin","Travis Page","Ryan Lipkin","Bo Tiller","Luke Miller","Matt Metz","Matt Clawson","Bo Tiller","Jordan Martin"],["Matt Clawson","Luke Miller","Payton Docheff","Ryan Lipkin","David Carnes","Alex Agueros","Matt Clawson","Payton Docheff","Matt Metz","Alex Agueros","Alex Agueros","Jordan Martin"],["Matt Clawson","Luke Miller","Seth Miller","Ryan Lipkin","Seth Miller","Seth Miller","Seth Miller","Travis Page","Matt Metz","Seth Miller","Seth Miller","Jordan Martin"]],"2025":[["Seth Miller","David Carnes","Alex Agueros","Luke Miller","Matt Clawson","Clint Hudson","David Carnes","Matt Metz","Ryan Lipkin","Matt Metz","David Carnes","Bo Tiller"],["David Carnes","Alex Agueros","Alex Agueros","David Carnes","David Carnes","Clint Hudson","Matt Clawson","Clint Hudson","Ryan Lipkin","Ryan Lipkin","Alex Agueros","Bo Tiller"],["Luke Miller","Luke Miller","Alex Agueros","Ryan Lipkin","Travis Page","Payton Docheff","Luke Miller","Alex Agueros","Luke Miller","David Carnes","Ryan Lipkin","Ryan Lipkin"],["Seth Miller","Seth Miller","Seth Miller","Ryan Lipkin","Luke Miller","Bo Tiller","Payton Docheff","Matt Metz","Seth Miller","Matt Metz","Matt Metz","Bo Tiller"],["Seth Miller","Alex Agueros","Alex Agueros","Luke Miller","Travis Page","Clint Hudson","Payton Docheff","Matt Metz","Ryan Lipkin","Payton Docheff","Ryan Lipkin","Bo Tiller"]],"2026":[["David Carnes","Matt Clawson","Alex Agueros","Seth Miller","Luke Miller","Bo Tiller","Luke Miller","Clint Hudson","Jordan Martin","Travis Page","David Carnes","Matt Clawson"],["Travis Page","David Carnes","Alex Agueros","Ryan Lipkin","Luke Miller","Bo Tiller","David Carnes","Clint Hudson","Ryan Lipkin","Luke Miller","Travis Page","Travis Page"],["Seth Miller","Payton Docheff","Alex Agueros","Matt Clawson","Ryan Lipkin","Bo Tiller","Matt Metz","Clint Hudson","Ryan Lipkin","Payton Docheff","Travis Page","Travis Page"],["Clint Hudson","Payton Docheff","Alex Agueros","Matt Clawson","Seth Miller","Bo Tiller","Matt Metz","Clint Hudson","Travis Page","Seth Miller","Matt Metz","Ryan Lipkin"],["Clint Hudson","Ryan Lipkin","Alex Agueros","Matt Clawson","Luke Miller","Bo Tiller","Matt Metz","Seth Miller","Jordan Martin","Seth Miller","Matt Clawson","Ryan Lipkin"]]}
m=re.search(r'const rookieBoards=(\{.*?\});\nconst nf=',s,re.S)
if not m: raise SystemExit("rookieBoards not found")
boards=json.loads(m.group(1))
for y,v in owners.items():
    if y in boards:
        boards[y].pop("owners",None)
        boards[y]["ownersByRound"]=v
s=s[:m.start(1)]+json.dumps(boards,separators=(',',':'))+s[m.end(1):]
new=r"""function renderDraftIntel(){
 const picks=rookiePicks[selectedManager]||[],scored=picks.filter(p=>p.year<=2023&&Number.isFinite(p.ppg)),box=document.getElementById('draftIntel');
 if(!scored.length){box.innerHTML=`<div class="intel-note">First-three-year draft intel appears when this manager has mature WR/RB picks with verified Half-PPR outcomes.</div>`;return}
 const avg=scored.reduce((a,p)=>a+p.ppg,0)/scored.length,best=[...scored].sort((a,b)=>b.ppg-a.ppg)[0],worst=[...scored].sort((a,b)=>a.ppg-b.ppg)[0];
 const allScored=Object.values(rookiePicks).flat().filter(p=>p.year<=2023&&Number.isFinite(p.ppg));
 const bucket=p=>Math.min(4,Number(p.pick.split('.')[0]));
 const base={};[1,2,3,4].forEach(r=>{const d=allScored.filter(p=>bucket(p)===r);base[r]=d.length?d.reduce((a,p)=>a+p.ppg,0)/d.length:null});
 const roundStats=[1,2,3,4].map(r=>{const d=scored.filter(p=>bucket(p)===r),a=d.length?d.reduce((z,p)=>z+p.ppg,0)/d.length:null;return{r,label:r===4?'Round 4+':`Round ${r}`,n:d.length,avg:a,delta:a==null||base[r]==null?null:a-base[r]}});
 const deltas=scored.map(p=>p.ppg-base[bucket(p)]).filter(Number.isFinite),adj=deltas.length?deltas.reduce((a,v)=>a+v,0)/deltas.length:null;
 box.innerHTML=`<div class="intel-card"><small>Avg 3Y PPG / Pick</small><b>${avg.toFixed(1)}</b><span>All mature WR/RB picks</span></div><div class="intel-card"><small>Round-Adjusted PPG</small><b>${adj==null?'—':(adj>=0?'+':'')+adj.toFixed(1)}</b><span>vs league avg at same round</span></div><div class="intel-card"><small>Best Pick</small><strong>${best.player}</strong><span>${best.year} · ${best.pick} · ${best.ppg.toFixed(1)} PPG</span></div><div class="intel-card"><small>Worst Pick</small><strong>${worst.player}</strong><span>${worst.year} · ${worst.pick} · ${worst.ppg.toFixed(1)} PPG</span></div>${roundStats.map(x=>`<div class="intel-card"><small>${x.label} Avg 3Y PPG</small><b>${x.avg==null?'—':x.avg.toFixed(1)}</b><span>${x.n} scored · ${x.delta==null?'':(x.delta>=0?'+':'')+x.delta.toFixed(1)+' vs league'}</span></div>`).join('')}<div class="intel-note">Round matters. The round-adjusted number compares each mature WR/RB pick with the league's average outcome from that same rookie-draft round, so a late-round hit gets more credit than simply stacking early picks. QB/TE picks and 2024–2026 classes remain in the draft history but are excluded from the completed first-three-year Half-PPR outcome average.</div>`;
}"""
s2=re.sub(r'function renderDraftIntel\(\)\{.*?\n\}',new,s,count=1,flags=re.S)
if s2==s: raise SystemExit("renderDraftIntel not replaced")
p.write_text(s2)
